-- DRAFT ONLY. Additive replacement after the existing binding migration.
-- Generated by the CLI; ordered after 20261024100000 to preserve dependencies.
-- No live database changes, privileges or automatic charges are authorized.
-- Previously bound attempts without a plan snapshot require manual review.
alter table billing.sumup_renewal_attempts
  add column if not exists expected_plan_id text,
  add column if not exists expected_plan_version integer;

create or replace function billing.prevent_sumup_renewal_snapshot_rewrite()
returns trigger
language plpgsql
security invoker
set search_path = pg_catalog, pg_temp
as $renewal_guard$
declare
  expected_price integer;
  effective_plan_id text;
  expected_currency text;
  expected_customer text;
  expected_plan_version integer;
  catalog_plan_version integer;
begin
  if tg_op = 'UPDATE' and old.provider_checkout_ref <> '' then
    if new.provider_checkout_ref is distinct from old.provider_checkout_ref
       or new.checkout_reference is distinct from old.checkout_reference
       or new.subscription_id is distinct from old.subscription_id
       or new.period_end is distinct from old.period_end
       or new.expected_customer_ref is distinct from old.expected_customer_ref
       or new.expected_amount_minor is distinct from old.expected_amount_minor
       or new.expected_currency is distinct from old.expected_currency
       or new.expected_next_period_end is distinct from old.expected_next_period_end
       or new.expected_plan_id is distinct from old.expected_plan_id
       or new.expected_plan_version is distinct from old.expected_plan_version then
      raise exception 'sumup_renewal_snapshot_immutable';
    end if;
  end if;

  if new.provider_checkout_ref <> '' then
    if new.expected_customer_ref is null or new.expected_customer_ref = ''
       or new.expected_amount_minor is null or new.expected_amount_minor <= 0
       or new.expected_currency is distinct from 'SEK'
       or new.expected_next_period_end is null
       or new.expected_next_period_end <= new.period_end then
      raise exception 'sumup_renewal_snapshot_incomplete';
    end if;
  end if;

  if new.provider_checkout_ref <> '' and
     (tg_op = 'INSERT' or (tg_op = 'UPDATE' and old.provider_checkout_ref = '')) then
    select p.price_minor, p.currency, s.provider_customer_ref,
           case when s.pending_plan_change = 'next_period' then p.version else s.plan_version end,
           p.version, p.plan_id
      into expected_price, expected_currency, expected_customer,
           expected_plan_version, catalog_plan_version, effective_plan_id
    from billing.subscriptions s
    join billing.plans p on p.plan_id = case
      when s.pending_plan_change = 'next_period' then s.pending_plan_id else s.plan_id end
      and p.active = true and p.plan_id <> 'plan.free'
    join billing.sumup_recurring_instruments i
      on i.subscription_id = s.subscription_id
     and i.user_id = s.user_id
     and i.provider_customer_ref = s.provider_customer_ref
     and i.status = 'verified'
    where s.subscription_id = new.subscription_id
      and s.provider = 'sumup'
      and s.status in ('ACTIVE', 'PAST_DUE')
      and not s.cancel_at_period_end
      and s.current_period_end = new.period_end;
    if expected_price is null or expected_price <= 0
       or expected_currency is distinct from 'SEK'
       or expected_customer is null or expected_customer = ''
       or expected_plan_version is distinct from catalog_plan_version
       or new.expected_plan_id is distinct from effective_plan_id
       or new.expected_plan_version is distinct from catalog_plan_version
       or new.expected_amount_minor is distinct from expected_price
       or new.expected_currency is distinct from expected_currency
       or new.expected_customer_ref is distinct from expected_customer then
      raise exception 'sumup_renewal_plan_price_mismatch';
    end if;
  end if;

  return new;
end;
$renewal_guard$;

drop trigger if exists sumup_renewal_snapshot_guard
  on billing.sumup_renewal_attempts;

create trigger sumup_renewal_snapshot_guard
before insert or update on billing.sumup_renewal_attempts
for each row execute function billing.prevent_sumup_renewal_snapshot_rewrite();

revoke all on function billing.prevent_sumup_renewal_snapshot_rewrite()
  from public, anon, authenticated, service_role;

create or replace function billing.bind_sumup_renewal_checkout_draft(
  p_checkout_reference text,
  p_provider_checkout_ref text,
  p_subscription_id text,
  p_period_end timestamptz,
  p_expected_next_period_end timestamptz
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
as $$
declare
  attempt billing.sumup_renewal_attempts;
  subscription billing.subscriptions;
  instrument billing.sumup_recurring_instruments;
  plan billing.plans;
begin
  if p_checkout_reference is null or p_checkout_reference !~ '^[A-Za-z0-9._:-]{1,64}$'
     or p_provider_checkout_ref is null or p_provider_checkout_ref !~ '^[A-Za-z0-9._:-]{1,80}$'
     or p_subscription_id is null or p_period_end is null
     or p_expected_next_period_end is null
     or p_expected_next_period_end is distinct from
       ((p_period_end at time zone 'UTC') + interval '1 month') at time zone 'UTC' then
    raise exception 'invalid_renewal_binding';
  end if;

  select * into subscription
  from billing.subscriptions s
  where s.subscription_id = p_subscription_id
  for update;

  if not found or subscription.provider is distinct from 'sumup'
     or subscription.status not in ('ACTIVE', 'PAST_DUE')
     or subscription.cancel_at_period_end
     or subscription.current_period_end is distinct from p_period_end
     or subscription.current_period_end > pg_catalog.now() then
    raise exception 'renewal_not_eligible';
  end if;

  select * into instrument
  from billing.sumup_recurring_instruments i
  where i.subscription_id = p_subscription_id
    and i.user_id = subscription.user_id
    and i.status = 'verified'
  for share;

  if not found or instrument.provider_customer_ref is null then
    raise exception 'renewal_instrument_missing';
  end if;

  select * into plan
  from billing.plans p
  where p.plan_id = case when subscription.pending_plan_change = 'next_period'
      then subscription.pending_plan_id else subscription.plan_id end
    and p.plan_id <> 'plan.free'
    and (subscription.pending_plan_change = 'next_period' or p.version = subscription.plan_version)
    and p.active = true
    and p.currency = 'SEK'
    and p.price_minor > 0;

  if not found or (subscription.pending_plan_id is null) is distinct from (subscription.pending_plan_change is null)
     or (subscription.pending_plan_change is not null and subscription.pending_plan_change <> 'next_period') then
    raise exception 'renewal_plan_invalid';
  end if;

  select * into attempt
  from billing.sumup_renewal_attempts a
  where a.subscription_id = p_subscription_id
    and a.period_end = p_period_end
  for update;

  if not found or attempt.checkout_reference is distinct from p_checkout_reference
     or attempt.status not in ('processing', 'reserved')
     or (attempt.provider_checkout_ref <> '' and attempt.provider_checkout_ref is distinct from p_provider_checkout_ref)
     or (attempt.expected_customer_ref is not null and attempt.expected_customer_ref is distinct from instrument.provider_customer_ref)
     or (attempt.expected_plan_id is not null and attempt.expected_plan_id is distinct from plan.plan_id)
     or (attempt.expected_plan_version is not null and attempt.expected_plan_version is distinct from plan.version)
     or (attempt.expected_amount_minor is not null and attempt.expected_amount_minor is distinct from plan.price_minor)
     or (attempt.expected_currency is not null and attempt.expected_currency is distinct from plan.currency)
     or (attempt.expected_next_period_end is not null and attempt.expected_next_period_end is distinct from p_expected_next_period_end) then
    raise exception 'renewal_binding_conflict';
  end if;

  if exists (
    select 1 from billing.sumup_renewal_attempts a
    where a.provider_checkout_ref = p_provider_checkout_ref
      and a.checkout_reference <> p_checkout_reference
  ) then
    raise exception 'renewal_checkout_already_bound';
  end if;

  update billing.sumup_renewal_attempts
  set provider_checkout_ref = p_provider_checkout_ref,
      expected_customer_ref = instrument.provider_customer_ref,
      expected_plan_id = plan.plan_id,
      expected_plan_version = plan.version,
      expected_amount_minor = plan.price_minor,
      expected_currency = plan.currency,
      expected_next_period_end = p_expected_next_period_end,
      status = 'processing',
      updated_at = pg_catalog.now()
  where checkout_reference = p_checkout_reference;

  return pg_catalog.jsonb_build_object('bound', true,
    'customer_id', instrument.provider_customer_ref, 'amount_minor', plan.price_minor,
    'currency', plan.currency, 'plan_id', plan.plan_id, 'plan_version', plan.version);
end;
$$;

revoke all on function billing.bind_sumup_renewal_checkout_draft(text, text, text, timestamptz, timestamptz)
  from public, anon, authenticated, service_role;
-- No EXECUTE grant. Grant only to a dedicated, audited worker role after end-to-end tests.

create or replace function billing.list_sumup_renewal_work_draft(p_limit integer)
returns table (
  subscription_id text, period_end timestamptz, customer_id text,
  amount_minor bigint, currency text, instrument_fingerprint text
)
language sql stable security definer
set search_path = pg_catalog, pg_temp
as $$
  select s.subscription_id, s.current_period_end, i.provider_customer_ref,
         coalesce(a.expected_amount_minor, p.price_minor)::bigint,
         coalesce(a.expected_currency, p.currency), i.instrument_fingerprint
  from billing.subscriptions s
  join billing.plans p on p.plan_id = case when s.pending_plan_change = 'next_period'
    then s.pending_plan_id else s.plan_id end
    and (s.pending_plan_change = 'next_period' or p.version = s.plan_version)
  join billing.sumup_recurring_instruments i
    on i.subscription_id = s.subscription_id and i.user_id = s.user_id
   and i.provider_customer_ref = s.provider_customer_ref and i.status = 'verified'
  left join billing.sumup_renewal_attempts a
    on a.subscription_id = s.subscription_id and a.period_end = s.current_period_end
  where s.provider = 'sumup' and s.status in ('ACTIVE', 'PAST_DUE')
    and not s.cancel_at_period_end and s.current_period_end <= pg_catalog.now()
    and p.active and p.currency = 'SEK' and p.price_minor > 0
    and p.plan_id <> 'plan.free'
    and ((s.pending_plan_id is null and s.pending_plan_change is null)
      or (s.pending_plan_id is not null and s.pending_plan_change = 'next_period'))
    and (a.status is null or a.status in ('reserved', 'created', 'processing'))
  order by s.current_period_end, s.subscription_id
  limit least(greatest(p_limit, 0), 100)
$$;
revoke all on function billing.list_sumup_renewal_work_draft(integer)
  from public, anon, authenticated, service_role;
-- Dedicated worker role is provisioned only after isolated end-to-end review.

create or replace function billing.commit_verified_sumup_renewal(
  p_checkout_reference text,
  p_subscription_id text,
  p_period_end timestamptz,
  p_provider_checkout_ref text,
  p_next_period_end timestamptz
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
as $$
declare
  attempt billing.sumup_renewal_attempts;
  subscription billing.subscriptions;
  updated billing.subscriptions;
begin
  if p_checkout_reference is null or p_checkout_reference !~ '^[A-Za-z0-9._:-]{1,64}$'
     or p_provider_checkout_ref is null or p_provider_checkout_ref !~ '^[A-Za-z0-9._:-]{1,80}$'
     or p_subscription_id is null or p_period_end is null or p_next_period_end is null
     or p_next_period_end <= p_period_end then
    raise exception 'invalid_renewal_commit';
  end if;

  select * into subscription from billing.subscriptions s
  where s.subscription_id = p_subscription_id for update;
  if not found or subscription.provider is distinct from 'sumup' then
    raise exception 'renewal_subscription_invalid';
  end if;

  select * into attempt from billing.sumup_renewal_attempts a
  where a.subscription_id = p_subscription_id and a.period_end = p_period_end
  for update;
  if not found or attempt.checkout_reference is distinct from p_checkout_reference then
    raise exception 'renewal_attempt_conflict';
  end if;

  if attempt.status = 'succeeded' then
    if attempt.provider_checkout_ref is distinct from p_provider_checkout_ref
       or attempt.expected_next_period_end is distinct from p_next_period_end
       or subscription.current_period_end < p_next_period_end then
      raise exception 'renewal_commit_conflict';
    end if;
    return pg_catalog.jsonb_build_object('committed', false, 'already_committed', true);
  end if;

  if attempt.status <> 'processing'
     or attempt.provider_checkout_ref is distinct from p_provider_checkout_ref
     or attempt.provider_checkout_ref = ''
     or attempt.expected_next_period_end is distinct from p_next_period_end
     or attempt.expected_customer_ref is null
     or attempt.expected_amount_minor is null
     or attempt.expected_amount_minor <= 0
     or attempt.expected_currency is distinct from 'SEK'
     or attempt.expected_plan_id is null or attempt.expected_plan_version is null
     or attempt.expected_plan_id is distinct from (case when subscription.pending_plan_change = 'next_period'
       then subscription.pending_plan_id else subscription.plan_id end)
     or (subscription.pending_plan_change is null and attempt.expected_plan_version is distinct from subscription.plan_version)
     or subscription.current_period_end is distinct from p_period_end
     or subscription.status not in ('ACTIVE', 'PAST_DUE')
     or subscription.cancel_at_period_end
     or not exists (
       select 1 from billing.plans p
       where p.plan_id = attempt.expected_plan_id
         and p.active = true
         and p.version = attempt.expected_plan_version
         and p.price_minor = attempt.expected_amount_minor
         and p.currency = attempt.expected_currency
     )
     or not exists (
       select 1 from billing.sumup_recurring_instruments i
       where i.subscription_id = subscription.subscription_id
         and i.user_id = subscription.user_id
         and i.provider_customer_ref = attempt.expected_customer_ref
         and i.status = 'verified'
     ) then
    raise exception 'renewal_commit_conflict';
  end if;

  updated := billing.advance_subscription_period(
    p_subscription_id, p_next_period_end, 'sumup_' || p_checkout_reference
  );
  if updated.current_period_end is distinct from p_next_period_end
     or updated.plan_id is distinct from attempt.expected_plan_id
     or updated.plan_version is distinct from attempt.expected_plan_version
     or updated.pending_plan_id is not null or updated.pending_plan_change is not null then
    raise exception 'renewal_period_not_advanced';
  end if;

  update billing.sumup_renewal_attempts
  set status = 'succeeded',
      provider_checkout_ref = p_provider_checkout_ref,
      updated_at = pg_catalog.now()
  where checkout_reference = p_checkout_reference;

  return pg_catalog.jsonb_build_object('committed', true, 'already_committed', false);
end;
$$;

revoke all on function billing.commit_verified_sumup_renewal(text, text, timestamptz, text, timestamptz)
  from public, anon, authenticated, service_role;
-- Intentionally NO execute grant. Never expose this commit RPC via service_role.
-- Verification must be enforced at the privileged boundary before enabling it.
